package com.gameaggregator.clientservice.domain;import jakarta.persistence.*;import java.time.*;import java.util.UUID;@Entity @Table(name="client_entitlements") public class ClientEntitlement{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID applicationId;@Column(nullable=false)public UUID gameId;@Column(nullable=false)public String territory;public Instant expiresAt;protected ClientEntitlement(){}public ClientEntitlement(UUID a,UUID g,String t,Instant e){applicationId=a;gameId=g;territory=t;expiresAt=e;}}
